programs.haiku:
"""Layer 15 MLP down_proj, component 2822.

What it does: a "non-universal quantity or absence" feature. It is high on words that
name an indefinite amount or an exclusion: without / non- (and their translations: ohne,
sans, без, 无, 非), nothing / something / anything, and existential quantifiers (some,
any, many, several, various, few, less, more). It is near zero on universal quantifiers
(all, both, each, every) and on most content words. It is mildly negative on prepositions
and conjunctions (in, on, to, for, or ...), on punctuation and on digits, and mildly
positive on size and extent adjectives (large, long, wide, very, specific).

The program reads only the newest token and gives it a fixed value by word class.
"""

from collections.abc import Mapping

READS: tuple[str, ...] = ()

# Exclusion and absence words: the strongest (about 2 to 3 units).
EXCLUSION = {
    "without", "non", "ohne", "sans", "без", "fewer", "nothing", "anything",
    "something", "numerous", "anybody", "无", "非", "無",
}

# Indefinite quantifiers and negators: moderate (about 0.5 to 1.2).
QUANTITY = {
    "no", "any", "many", "much", "several", "various", "different", "multiple",
    "certain", "lot", "variety", "less", "few", "more", "some", "someone", "anyone",
    "somebody", "somewhere", "anywhere", "nowhere", "neither", "never", "same",
    "most", "enough", "another",
}

# "not" and "only" are real but weaker than the quantifiers above.
WEAK_NEGATION = {"not", "only", "one", "two", "three"}

# Size and extent adjectives: a little positive.
EXTENT = {"large", "larger", "longer", "long", "wide", "vast", "broad", "very", "specific", "low"}

# Prepositions and conjunctions: slightly negative.
FUNCTION = {
    "in", "on", "to", "for", "by", "at", "from", "after", "into", "between",
    "through", "under", "onto", "or", "but", "and", "is", "are", "be",
}

DIGITS = set("0123456789")


def value_of(word: str) -> float:
    if word in EXCLUSION:
        return 2.2
    if word in QUANTITY:
        return 0.9
    if word in WEAK_NEGATION:
        return 0.4
    if word in EXTENT:
        return 0.7
    if word in FUNCTION:
        return -0.15
    if word in DIGITS:
        return -0.05
    if not any(ch.isalnum() for ch in word):
        return -0.07  # punctuation and whitespace-only tokens
    return 0.0


def step(carry, prefix, upstream: Mapping):
    # The newest token, as its own text, lower-cased with its leading space removed.
    word = prefix.token_strings[-1].strip().lower()
    return carry, value_of(word)

"""Layer 15 MLP down_proj, component 2825: a weak, mostly word-driven predictor.

What the component is: one rank-one piece of the MLP down projection. It reads the MLP's
hidden units through a direction that is mostly spread over many units, and writes a small
vector into the residual stream. Its activation is usually near zero, with spread about 0.6.
Its activation depends on context in a diffuse way: no token, token class, or previous token
explains much of it, so this program only captures the coarse word-level tendencies below.

What the program does: it looks only at the newest token's word (lower-cased, no space).
  - numerals and ordinals ("one", "first") push the activation clearly negative (about -0.4);
  - quantifiers, wh-words, modals and a few adjectives ("each", "why", "may", "high") push it
    mildly negative (about -0.24);
  - prepositions and clause openers ("in", "before", "if") push it mildly negative (about -0.17);
  - the conjunctions "and", "or", "than" push it positive (about +0.19);
  - every other token predicts the typical value (about -0.07);
  - the first token of a row predicts 0, since the activation there is always near 0.

The values are the mean activation of each group on 8192 training rows (4.2M positions).
Its variance explained is under 1%, so it is a rough sketch and not a faithful description.
A table of per-token means would reach about 3 to 4% out of sample, but it is a table of
arbitrary token ids, so it is not used here.
"""

from collections.abc import Mapping

READS: tuple[str, ...] = ()

NUMERALS = set(
    "one two three four five six seven eight nine ten first second third last next".split()
)
QUANTIFIERS_ETC = set(
    "each every any all some no this these those both many few more most less much "
    "what why how whether which who whom whose where when "
    "may might shall should must can could will would "
    "good high long big new old maximum minimum start".split()
)
PREPOSITIONS_ETC = set(
    "in on for of into within inside before after under over while if".split()
)
CONJUNCTIONS = {"and", "or", "than"}

OTHER_VALUE = -0.067
VALUES = {"numeral": -0.415, "quantifier": -0.242, "preposition": -0.171, "conjunction": 0.187}


def word_class(token: str) -> str | None:
    word = token.strip().lower()
    if word in NUMERALS:
        return "numeral"
    if word in QUANTIFIERS_ETC:
        return "quantifier"
    if word in PREPOSITIONS_ETC:
        return "preposition"
    if word in CONJUNCTIONS:
        return "conjunction"
    return None


def step(carry, prefix, upstream: Mapping):
    if prefix.position == 0:
        return carry, 0.0
    cls = word_class(prefix.token_strings[-1])
    return carry, VALUES.get(cls, OTHER_VALUE)

"""Layer 15 MLP unit 2839's down-projection component: a concept table.

What it is: a rank-one readout of the layer-15 MLP hidden units. Its value is
dominated by many small, context-dependent contributions with no token or
surface signature (a per-token lookup explains ~0% of its variance). Only a few
token groups have a consistent mean, so this program predicts those group means
and 0 everywhere else:

- a triple-quote that opens a docstring or string block: strongly negative;
- reference and parameter-note words (See, Id, Not, Default, Required): negative;
- biographical "born": positive;
- colons and full stops: weakly negative (colons are the most common signal).

The values are the groups' mean activations on training rows.
"""

READS = ()

DOCSTRING_OPEN = {' """', ' """\n'}
NOTE_WORDS = {' See', ' Id', ' Not', ' Default', 'Default', ' Required', 'Required', '.-'}
BIRTH_WORDS = {'born', 'Born'}
VALUES = {}
for _t in DOCSTRING_OPEN:
    VALUES[_t] = -2.0
for _t in NOTE_WORDS:
    VALUES[_t] = -0.7
for _t in BIRTH_WORDS:
    VALUES[_t] = 1.3
VALUES[':'] = -0.25
VALUES['.'] = -0.08


def step(carry, prefix, upstream):
    """Predict the group mean for the newest token, 0 for every other token."""
    return carry, VALUES.get(prefix.token_strings[-1], 0.0)

"""Definition-introducing tokens.

Component p-82af68dd@100000/layers.15.mlp.down_proj:2843 is diffuse: most of its activation
is small and not readable from the surface text. Its clearest large positive values occur
where the text is about to *define* something: an assignment to a named variable in code
(`const x = ...`, strongest), `:=`, a defining verb (`X denotes`, `X represents`,
`X specifies`, `X implements`), `stands for` / `short for` before an expansion, `by`, and
the first word of an expansion after `ABBR (`.

This program predicts one fixed value per such cue, and 0 elsewhere. A lone-letter `=`
(as in maths, `x = 2`) gets a small value, other `=` a middling one.
"""

import re
from collections.abc import Mapping

READS: tuple[str, ...] = ()

DEFINING_VERBS = {
    "denotes": 2.7, "denote": 0.8, "represents": 1.0, "specifies": 1.9,
    "constructs": 1.8, "implements": 1.2, "extends": 1.0, "defines": 1.5,
    "describes": 0.8, "means": 0.5,
}
IDENTIFIER = re.compile(r"[A-Za-z_][A-Za-z0-9_.]+")
ACRONYM = re.compile(r"[A-Z]{2,}[0-9]*")


def step(carry, prefix, upstream: Mapping):
    strings = prefix.token_strings
    word = strings[-1].strip()
    before = strings[-2].strip() if len(strings) > 1 else ""
    if word == "=":
        # Code assignment to an identifier is a definition; a lone letter (math) is not.
        if IDENTIFIER.fullmatch(before) and len(before) > 1:
            value = 0.9
        elif len(before) == 1:
            value = 0.2
        else:
            value = 0.6
    elif word == ":=":
        value = 1.4
    elif word in DEFINING_VERBS:
        value = DEFINING_VERBS[word]
    elif word == "for" and before in ("stands", "short", "stand"):
        value = 2.6
    elif word == "by":
        value = 0.7
    elif before == "(" and len(strings) > 2 and ACRONYM.fullmatch(strings[-3].strip()):
        value = 0.5
    else:
        value = 0.0
    return carry, float(value)

"""Component 2844 of layer 15's MLP down_proj, read as a conditional-logic detector.

Its activation is almost exactly one MLP hidden unit (layer 15, unit 2844) scaled by a
constant. Its large values sit in conditional code and prose: the words of an `if` /
`unless` / `when` line that compare or test something. The program's rules, with
coefficients fitted to the activations of 16k training rows:
  - on an `if`-style line, `if`-words (+0.6), comparisons such as `==`, `not`, `>`, `is`
    (+0.3) push it up a little; error-check names `err`, `e`, `Exception` (-1) push it down;
  - a null value (`nil`, `null`, `None`) right after `==` pushes it strongly up (+4), and
    right after `!=` strongly down (-3.2);
  - any token right after `!=` is pushed down a little (-0.3);
  - branch-alternative keywords (`else`, `elif`, `case`, `catch`, ...) are pushed down (-0.4).
Everywhere else it predicts a small baseline (0.035). This explains only about 1% of the
variance: most of its variance is spread over ordinary tokens that no token- or
line-level rule captures.
"""

import re

READS = ()

IF_WORDS = {"if", "If", "elif", "unless", "Unless", "when"}
COMPARE = {"==", "===", "is", "not", ">", "<", ">=", "<=", "in", "&&", "||", "len", "typeof", "isinstance"}
NULL_WORDS = {"nil", "null", "None", "none", "NULL", "undefined"}
EQUAL_OPS = {"==", "===", "is", "typeof", ">", "<"}
NOT_EQUAL_OPS = {"!=", "!=="}
ERROR_NAMES = {"err", "e", "Exception", "error", "exc", "ex", "catch"}
BRANCH_ALTERNATIVES = {"else", "elif", "case", "default", "switch", "catch", "except"}


def step(carry, prefix, upstream):
    # carry: (words of the current line so far, whether that line is a conditional, document)
    line, doc = carry[:2] if carry is not None else ("", None)
    tok = prefix.token_strings[-1].strip()
    doc_id = prefix.document_ids[-1]
    prev = prefix.token_strings[-2].strip() if len(prefix.token_strings) > 1 else ""
    if prefix.position == 0 or doc_id != doc:
        line, prev = "", ""
    raw = prefix.token_strings[-1]
    line = (line + raw).split("\n")[-1][-200:]
    in_if = any(w in IF_WORDS for w in re.findall(r"\w+", line))
    value = 0.035
    if prev in NOT_EQUAL_OPS:
        value -= 0.3
    if in_if:
        value += 0.04
        if tok in IF_WORDS:
            value += 0.57
        if tok in COMPARE:
            value += 0.28
        if tok in NULL_WORDS:
            if prev in EQUAL_OPS:
                value += 4.0
            elif prev in NOT_EQUAL_OPS:
                value -= 3.2
        if tok in ERROR_NAMES:
            value -= 1.0
    if tok in BRANCH_ALTERNATIVES:
        value -= 0.4
    return (line, doc_id, in_if), value

"""Block openers: the component goes strongly negative on the break that opens a
block of structured content (a list, code, equation), and near zero elsewhere.

- A colon followed by a blank line ("...as follows:\n\n", "...is:\n\n") or a code
  fence ("```") is the strongest case; a colon right before a list is most negative
  after lead-in words such as "is", "are", "as", "follows".
- A colon followed by a single newline, display math ("$$"), and a line break right
  after a tool tag are weaker openers.
- Other line breaks are mildly negative; code operators and comment markers
  ("//", "#", "}", "->") are mildly positive; all other tokens sit near zero.
The model's sign and rough size are captured; the diffuse variation on ordinary
words and punctuation is not modelled.
"""
import re

READS = ()

LEAD_IN = {"is", "are", "as", "follows", "following", "be", "below", "equation"}
FENCE_AND_MATH = {"```", "``", "$$", " $$"}
TOOL_TAGS = {"<tool_call>", "<tool_response>"}
CODE_OPS = {" //", "//", " #", "#", "--", " }", " ->", " =", "][", "{", "_"}


def step(carry, prefix, upstream):
    t = prefix.token_strings[-1]
    before = prefix.token_strings[-2].strip() if len(prefix.token_strings) > 1 else ""
    if re.search(r"[:：]\n\n", t) or t == "```":
        return carry, -11.0 if before in LEAD_IN else -7.0
    if re.search(r"[:：]\n", t):
        return carry, -2.0
    if t in FENCE_AND_MATH:
        return carry, -3.0
    if before in TOOL_TAGS and "\n" in t:
        return carry, -3.0
    if "\n" in t:
        return carry, -0.45
    if t in CODE_OPS:
        return carry, 0.3
    return carry, 0.0

"""Layer 15 MLP down-projection, component 2854.

Mostly near zero. Its large values are negative spikes on the start of a web
address: "http" or "https" goes strongly negative (about -35 on average; about
-50 when the link is in prose or markup, as after "](", " at", " See" or " <",
and about -20 when it sits in a quoted string or code). The first tokens after
the address are mildly negative. A digit right after an approximation sign
("≈0", "~0") is also negative: about -25 for a zero, -5 for another digit.
Link and markup words (display, label, ref, github, doi, cite, www) are weakly
negative. Words of surprise and plausibility ("surprising", "plausible",
"ordinary", "reasonable") are mildly positive.
"""

READS = ()

URL_START = {"http", "https"}
LINK_CUE = {"](", " at", " See", " see", " <", "(", ":", " visit", " from", " to", " //", " :", ".", ":\n"}
QUOTE_CUE = {' "', " '", '("', "('", " `", ' \\"', " =", " *", ",", ")", "(w", " "}
APPROX_SIGNS = {"≈", "~", "�"}
MARKUP = {"display", "label", "ref", "href", "cite", "doi", "github", "ithub", "www", "issue", "-label"}
SURPRISE = {
    "surprise", "surprising", "surprised", "astonishing", "plausible", "ordinary",
    "reasonable", "justified", "readily", "easily", "unfair", "wonder", "unusual",
    "strange", "logical", "unexpected",
}


def step(carry, prefix, upstream):
    t = prefix.position
    doc = prefix.document_ids

    def back(k):
        # the token k places before this one (raw text), if it is in the same document
        i = t - k
        if i < 0 or doc[i] != doc[t]:
            return ""
        return prefix.token_strings[i]

    cur = back(0).strip()
    prev, prev2 = back(1), back(2)
    if cur in URL_START:
        if prev in LINK_CUE:
            value = -50.0
        elif prev in QUOTE_CUE:
            value = -20.0
        else:
            value = -35.0
    elif prev.strip() in URL_START or prev2.strip() in URL_START:
        value = -1.5  # the tokens just inside a web address
    elif cur.isdigit() and prev.strip() in APPROX_SIGNS:
        value = -25.0 if cur == "0" else -5.0
    elif cur in MARKUP:
        value = -3.0
    elif cur in SURPRISE:
        value = 3.0
    elif cur.isdigit():
        value = -0.2
    else:
        value = 0.0
    return carry, value

"""Layer 15, MLP hidden unit 2856 (component 2856 of layers.15.mlp.down_proj).

This component is one MLP neuron: its input direction is almost entirely the
hidden unit 2856 (weight 0.93 of norm 1.09), and its output direction is written
back to the residual stream with norm 1.46. So its activation is the neuron's
value scaled by about 1.36: silu(gate . x) * (up . x) for the normalized residual x.

No simple concept captures its size or sign. Token identity explains about 3% of
its variance with a full per-token table, and the concept rules below explain
under 1%. The program keeps only the parts that are readable:
  - the first token of each document is 0 (the neuron is silent there);
  - markdown heading hashes (#, ##, ####) push it negative;
  - chat-template markers (<|im_start|>, <think>, ...) and code closers
    ("][", "){", "cd") push it positive;
  - a line-break-only token pushes it slightly negative;
  - everything else sits at its typical value, about -0.07.
"""

from collections.abc import Mapping
import re

READS: tuple[str, ...] = ()

HEADING = re.compile(r"\s*#+\s*")
CHAT = re.compile(r"<\|im_start\|>|<\|im_end\|>|<think>|</think>|<tool_call>|</tool_call>|<tool_response>|</tool_response>")
CODE_CLOSE = {"][", "[[", "[]", "]:", ":[", ".[", "){", ">&", "cd", "/bin", '">', "})", "});"}
TYPICAL = -0.07


def step(carry, prefix, upstream: Mapping):
    t = prefix.position
    if t == 0 or prefix.document_ids[t] != prefix.document_ids[t - 1]:
        return carry, 0.0
    s = prefix.token_strings[-1]
    if HEADING.fullmatch(s):
        return carry, -0.4
    if CHAT.fullmatch(s.strip()):
        return carry, 0.3
    if s.strip() in CODE_CLOSE:
        return carry, 0.4
    if s.strip() == "" and "\n" in s:
        return carry, -0.15
    return carry, TYPICAL

"""Layer 15 MLP hidden unit 2865 (down_proj component 2865), read as a word-class detector.

What it does: the component's activation depends mostly on which kind of token it is
looking at. It is high on adjectives, copulas and auxiliaries ("is", "was", "been"),
verbs, and content words; near zero on nouns, digits and most word pieces; and negative
on punctuation, pronouns, and conjunctions/prepositions such as "or", "and", "of", "to",
"in". This program assigns each token its word class and returns that class's mean
activation, measured on sampled training text. It keeps no state.

Word classes come from closed word lists (conjunctions/prepositions, determiners,
auxiliaries, pronouns) and from WordNet's parts of speech for other English words.
Everything else falls into a surface class: punctuation, digits, CJK, whitespace, or
a word piece that continues a word.
"""

import re
from functools import lru_cache

import wordnet

READS = ()

CONJ_PREP = set(
    "and or but of to in on at for with from by because if that as than which who whom "
    "while although though so where when into about over under between through without "
    "within nor yet unless until since whether either neither".split()
)
DET = set("the a an this these those each every some any all no".split())
AUX = set("is was be been are were being am has have had do does did will would can could should may might must shall".split())
PRON = set("he she it they we you i his her its their our my your him them us me".split())

# Mean activation of each word class over sampled training tokens.
MEAN = {
    "adj": 0.56, "aux": 0.52, "verb": 0.39, "nounverb_adj": 0.28, "nospace_alpha": 0.22,
    "det": 0.21, "cjk": 0.18, "digit": 0.14, "adv": 0.12, "partial": 0.12, "noun": 0.11,
    "alpha_none": 0.06, "ws": 0.05, "pron": -0.05, "punct": -0.10, "conj_prep": -0.47,
}


@lru_cache(maxsize=None)
def word_class(s):
    """The word class of one token's text `s`."""
    w = s.strip().lower()
    if s[:1] == " " and re.fullmatch(r"[a-z]+", w):
        if w in CONJ_PREP:
            return "conj_prep"
        if w in DET:
            return "det"
        if w in AUX:
            return "aux"
        if w in PRON:
            return "pron"
        pos = wordnet.parts_of_speech(w)
        if not pos:
            return "alpha_none"
        if pos == {"adjective"}:
            return "adj"
        if pos == {"verb"}:
            return "verb"
        if pos == {"adverb"}:
            return "adv"
        if "noun" in pos and not ("verb" in pos or "adjective" in pos):
            return "noun"
        return "nounverb_adj"
    if re.fullmatch(r"\s*[0-9]+", s):
        return "digit"
    if re.fullmatch(r"\s?[^\w\s]+", s):
        return "punct"
    if s.strip() == "":
        return "ws"
    if re.search(r"[　-鿿가-힯]", s):
        return "cjk"
    if "�" in s:
        return "partial"
    return "nospace_alpha"


def step(carry, prefix, upstream):
    """The activation at this position: the mean for the newest token's word class."""
    return None, MEAN[word_class(prefix.token_strings[-1])]

"""A weak, token-class reading of layer 15's MLP component 2872.

This component is a diffuse feature: its activation is large in both directions (about
+/-0.5 typical, up to 10+) yet almost none of it follows from the token itself. The
program below predicts it from three readable word classes, each given the average
activation measured on training text:

- relative-path navigation (`../`, `./` inside a quoted path or import): about +1.4
- project sandbox and architecture names (`bed` and `workspace` in `/testbed` and
  `/workspace`, `test`; class-name suffixes such as DAO, Activity, Service, Entity;
  Android-style `.layout`, `.dao`, `.entity` after a dot): about +0.6 to +2.7
- chat-template markers (`assistant`, `<|endoftext|>`, `<|im_start|>`): about -0.3

Every other token predicts 0. The program keeps no state: each position is judged from its
own token alone.
"""

import re

READS = ()

RELATIVE_PATH = re.compile(r"\.\.?/")
SANDBOX_WORDS = {"bed", "workspace", "test"}
ARCHITECTURE_NAME = re.compile(
    r"(Activity|DAO|Dao|DTO|Dto|Service|ServiceImpl|Entity|Controller|Repository"
    r"|Facade|Util|Utils|Helper|Dialog|ViewModel|Manager|Factory|Model|Menu)$"
)
DOT_RESOURCE = re.compile(
    r"\.(layout|activity|dao|dto|menu|services?|drawable|entity|repository|domain"
    r"|controller|utilities)"
)
CHAT_MARKERS = {"assistant", "user", "<|endoftext|>", "<|im_start|>", "<|im_end|>"}


def step(carry, prefix, upstream):
    word = prefix.token_strings[prefix.position].strip()
    if DOT_RESOURCE.fullmatch(word):
        value = 2.7
    elif RELATIVE_PATH.search(word):
        value = 1.4
    elif word in SANDBOX_WORDS:
        value = 0.9
    elif ARCHITECTURE_NAME.search(word):
        value = 0.6
    elif word in CHAT_MARKERS:
        value = -0.3
    else:
        value = 0.0
    return carry, float(value)

"""Layer 15 MLP hidden unit 2873, read through its down_proj component, as a
"recipient / goal" detector.

The component's activation is largely this one MLP hidden unit's value (correlation
about 0.8 on sampled text). The unit is large and positive on a word that is the
recipient or goal of an action: an object pronoun right after "to" ("to [whom]"),
after a verb of giving, telling or providing ("give [you]", "tell [him]", "provide
[them]"), or after a preposition ("with [you]"). The Japanese dative/locative
particles に, を and へ (家に, 財布に) are also positive, に most strongly. It is pushed negative
on subject pronouns that open a clause ("when [I]", "while [he]", "that [they]") and
on possessive determiners.

The program scores the word just read with these word lists and a few weights, set
from group means over training text. It explains only a small share of the
component's variance (about 2% on eval): most of its spread comes from context that
word lists cannot see, and the rare large spikes (at commas and periods, among
others) are missed. Its effect on the model's output is small, as the component's own effect is.
"""

from collections.abc import Mapping

READS: tuple[str, ...] = ()

# Object pronouns, which can be a recipient or goal.
OBJECT_PRONOUNS = {"you", "him", "her", "me", "us", "them", "whom", "it"}
# Verbs of giving, telling, providing, paying and sending: a recipient follows.
GIVING_VERBS = {
    "give", "gave", "given", "giving", "gives", "tell", "told", "telling",
    "show", "showed", "provide", "provided", "providing", "pay", "paid",
    "send", "sent", "offer", "offered", "assure", "assured", "let", "lend",
    "teach", "taught", "bring", "brought", "write", "wrote", "receive", "received",
}
# Other prepositions that introduce a goal or companion.
PREPOSITIONS = {"with", "for", "of", "at", "from", "into", "on", "in", "about", "against", "before"}
# Words that open a subordinate clause, so a following pronoun is a subject.
SUBORDINATORS = {"if", "when", "while", "that", "because", "as", "where", "what", "so", "who"}
# Subject pronouns.
SUBJECT_PRONOUNS = {"i", "he", "she", "they", "we", "who"}
# Possessive determiners.
POSSESSIVES = {"my", "your", "his", "her", "their", "its", "our"}
# Japanese dative/locative particles.
DATIVE_PARTICLES = {"に", "へ", "を"}


def _word(token: str) -> str:
    return token.strip().lower()


def _recipient_value(prev: str) -> float:
    """How strongly an object pronoun reads as a recipient, given the word before it."""
    if prev == "to":
        return 3.6
    if prev in GIVING_VERBS:
        return 2.0
    if prev in PREPOSITIONS:
        return 1.2
    if prev in SUBORDINATORS:
        return 0.1
    return 0.4


def step(carry, prefix, upstream: Mapping):
    word = _word(prefix.token_strings[-1])
    same_doc = len(prefix.document_ids) > 1 and prefix.document_ids[-2] == prefix.document_ids[-1]
    prev = _word(prefix.token_strings[-2]) if same_doc else ""

    value = 0.06
    if word in OBJECT_PRONOUNS:
        value += _recipient_value(prev)
    elif word in DATIVE_PARTICLES:
        value += 3.3
    elif word in SUBJECT_PRONOUNS and prev in SUBORDINATORS:
        value -= 0.2
    elif word in POSSESSIVES:
        value -= 0.15
    return carry, float(value)
